import{_ as a,o as s,c as o,a2 as t}from"./chunks/framework.BDCokyix.js";const h=JSON.parse('{"title":"Dependency and Workspace Policy","description":"","frontmatter":{},"headers":[],"relativePath":"development/dependencies.md","filePath":"development/dependencies.md","lastUpdated":1780254295000}'),i={name:"development/dependencies.md"};function d(r,e,n,c,p,l){return s(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="dependency-and-workspace-policy" tabindex="-1">Dependency and Workspace Policy <a class="header-anchor" href="#dependency-and-workspace-policy" aria-label="Permalink to &quot;Dependency and Workspace Policy&quot;">​</a></h1><p>This repository uses Cargo workspaces and a single source of truth for dependency versions.</p><h2 id="rust-cargo" tabindex="-1">Rust (Cargo) <a class="header-anchor" href="#rust-cargo" aria-label="Permalink to &quot;Rust (Cargo)&quot;">​</a></h2><ul><li><strong>All third-party dependency versions live in</strong> the repo root <code>Cargo.toml</code> under <code>[workspace.dependencies]</code>.</li><li><strong>Every crate and binary</strong> under <code>backend/crates/*</code> and <code>backend/bins/*</code> must depend on third-party crates using: <ul><li><code>crate-name = { workspace = true }</code></li><li>add <code>features = [...]</code> in the leaf crate if needed.</li></ul></li><li><strong>Do not</strong> put <code>version = &quot;...&quot;</code> for third-party crates in leaf <code>Cargo.toml</code> files.</li></ul><p>This keeps dependency upgrades simple, avoids version skew, and makes feature usage explicit at the call site.</p><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li>New third-party dependencies should be added to root <code>Cargo.toml</code> first, then consumed in leaf crates with <code>{ workspace = true }</code>.</li><li>Existing non-compliant leaf pins should be treated as migration debt and removed opportunistically when touching that crate.</li></ul><h2 id="desktop-pnpm" tabindex="-1">Desktop (pnpm) <a class="header-anchor" href="#desktop-pnpm" aria-label="Permalink to &quot;Desktop (pnpm)&quot;">​</a></h2><ul><li>Desktop dependencies are managed via the <code>pnpm</code> workspace under <code>desktop/</code>.</li><li>Install and run scripts via <code>pnpm</code> (not <code>npm</code>).</li></ul><h2 id="docs-vitepress" tabindex="-1">Docs (VitePress) <a class="header-anchor" href="#docs-vitepress" aria-label="Permalink to &quot;Docs (VitePress)&quot;">​</a></h2><p>Docs are built with VitePress (Node-based) from the <code>docs/src</code> markdown tree via the <code>@soma/docs</code> workspace package. Use the root scripts (or <code>pnpm --filter @soma/docs run dev/build</code> directly):</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # dev server</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # outputs to ./site</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="repo-automation-cargo-xtask" tabindex="-1">Repo automation (<code>cargo xtask</code>) <a class="header-anchor" href="#repo-automation-cargo-xtask" aria-label="Permalink to &quot;Repo automation (`cargo xtask`)&quot;">​</a></h2><p>Repo automation lives in <code>xtask/</code> and is invoked via <code>cargo xtask ...</code> (wired through <code>.cargo/config.toml</code>). CI uses this for Cargo workspace version resolution. The desktop app is the Tauri V2 shell at <code>desktop/desktop-app/</code>; its bundle is produced by <code>tauri build</code>. The server release pipeline lives in <code>.github/workflows/release-server.yml</code> (a Tauri desktop release workflow is not yet wired).</p>',14)])])}const k=a(i,[["render",d]]);export{h as __pageData,k as default};
